	private static void check(RepositoryConnection connection, Set<Statement> all, Resource subject, IRI predicate,
			Value object, Resource[] contexts, List<String> mismatches) {
		Set<Statement> expected = new HashSet<>();
		for (Statement statement : all) {
			if (matches(statement, subject, predicate, object, contexts)) {
				expected.add(statement);
			}
		}
		Set<Statement> actual = statements(connection, subject, predicate, object, contexts);
		if (!actual.equals(expected)) {
			mismatches.add("(" + subject + ", " + predicate + ", " + object + ", " + List.of(contexts)
					.stream()
					.map(String::valueOf)
					.toList() + "): expected " + expected + " but was " + actual);
		}
	}

	private static boolean matches(Statement statement, Resource subject, IRI predicate, Value object,
			Resource[] contexts) {
		if (subject != null && !subject.equals(statement.getSubject())
				|| predicate != null && !predicate.equals(statement.getPredicate())
				|| object != null && !object.equals(statement.getObject())) {
			return false;
		}
		if (contexts.length == 0) {
			return true;
		}
		for (Resource context : contexts) {
			if (Objects.equals(context, statement.getContext())) {
				return true;
			}
		}
		return false;
	}

	private static Set<Statement> statements(RepositoryConnection connection, Resource subject, IRI predicate,
			Value object, Resource... contexts) {
		Set<Statement> statements = new HashSet<>();
		try (RepositoryResult<Statement> result = connection.getStatements(subject, predicate, object, false,
				contexts)) {
			result.forEach(statements::add);
		}
		return statements;
	}

	private static void add(RepositoryConnection connection, Set<Statement> expected, Resource subject, IRI predicate,
			Value object, Resource context) {
		connection.add(subject, predicate, object, context);
		expected.add(F.createStatement(subject, predicate, object, context));
	}

	private static IRI iri(String local) {
		return F.createIRI("http://example.org/interleaving/" + local);
	}
